// ===== Agendamento da Agenda: um endereço só pra tudo que mexe em data/hora =====
//
// Modos aceitos no corpo do pedido:
//   cancelar=true                          -> só muda o Status pra Cancelado
//   desagendar=true                        -> limpa Reservado_Inicio/Fim (volta pra fila)
//   confirmarData=true|false               -> só muda o Status, mantém o horário
//   data + semHorario=true                 -> dia marcado, horário ainda não definido
//   data + reservadoInicio + reservadoFim  -> agendamento exato
//
// Qualquer modo com horário também aceita trocarComId (+ trocaData/trocaDataFim/
// trocaInicio/trocaFim/trocaSemHorario/trocaDesagendar/trocaStatus) pra trocar
// dois chamados de lugar. Os dois vão no MESMO PATCH: ou os dois mudam ou
// nenhum muda, nunca metade da troca salva.
//
// A checagem de conflito acontece AQUI, no servidor, não só na tela: a regra é
// novoInicio < outroFim && novoFim > outroInicio -- encostado (um termina
// 10:00 e o outro começa 10:00) NÃO é conflito.

const FUSO = "-03:00";
const INICIO_DIA = "08:00", FIM_DIA = "18:00";
const TABELA = "https://api.airtable.com/v0/app6PyYmtFduIMp7B/tbltipxOIw8F96QHO";
const AGUARDANDO = "Aguardando confirmação de data";
const AGENDADO = "Agendado";

// Horário de Brasília fixo (-03:00, sem horário de verão atualmente) -- grava
// explícito pra não depender de como o servidor interpreta data sem fuso.
function isoBrasilia(data, hhmm) { return data + "T" + hhmm + ":00" + FUSO; }

// Extrai "HH:MM"/"YYYY-MM-DD" em horário de Brasília de qualquer ISO (vem em
// -03:00 ao montar aqui, mas vem em UTC/"Z" ao reler do Airtable) -- não dá
// pra só cortar a string, tem que converter de verdade.
function paredeBrasilia(iso) { return new Date(new Date(iso).getTime() - 3 * 3600000); }
function horaLocalBrasilia(iso) {
  const d = paredeBrasilia(iso);
  return String(d.getUTCHours()).padStart(2, "0") + ":" + String(d.getUTCMinutes()).padStart(2, "0");
}
function diaLocalBrasilia(iso) { return paredeBrasilia(iso).toISOString().slice(0, 10); }

// Duas janelas de tempo se cruzam se uma começa antes da outra terminar, nos
// dois sentidos.
function seCruzam(aIni, aFim, bIni, bFim) {
  return new Date(aIni) < new Date(bFim) && new Date(bIni) < new Date(aFim);
}

function somaDiasStr(dataStr, dias) {
  const d = new Date(dataStr + "T12:00:00Z");
  d.setUTCDate(d.getUTCDate() + dias);
  return d.toISOString().slice(0, 10);
}

function montaSugestao(cursorIso, duracaoMs) {
  const fimIso = new Date(new Date(cursorIso).getTime() + duracaoMs).toISOString();
  return {
    data: diaLocalBrasilia(cursorIso), inicio: horaLocalBrasilia(cursorIso),
    fim: horaLocalBrasilia(fimIso), inicioIso: cursorIso, fimIso,
  };
}

// Primeira folga com a duração pedida, a partir da data dada, olhando alguns
// dias à frente. Só sugere dentro do horário de trabalho -- é sugestão, marcar
// fora continua permitido.
function achaHorarioLivre(dataInicial, duracaoMs, ocupados) {
  for (let i = 0; i < 30; i++) {
    const dataStr = somaDiasStr(dataInicial, i);
    const doDia = ocupados
      .filter((o) => diaLocalBrasilia(o.inicioIso) === dataStr || diaLocalBrasilia(o.fimIso) === dataStr)
      .sort((a, b) => new Date(a.inicioIso) - new Date(b.inicioIso));

    let cursor = isoBrasilia(dataStr, INICIO_DIA);
    const fimDoDia = isoBrasilia(dataStr, FIM_DIA);
    for (const o of doDia) {
      if (new Date(o.inicioIso) - new Date(cursor) >= duracaoMs) return montaSugestao(cursor, duracaoMs);
      if (new Date(o.fimIso) > new Date(cursor)) cursor = o.fimIso;
    }
    if (new Date(fimDoDia) - new Date(cursor) >= duracaoMs) return montaSugestao(cursor, duracaoMs);
  }
  return null;
}

// Recusa = não grava nada e responde o motivo. A tela usa isso pra devolver o
// card pro lugar de antes (nunca pode ficar mostrando que deu certo).
function recusa(mensagem, extra) {
  return [{ json: { recusar: true, resposta: Object.assign({ ok: false, mensagem }, extra || {}) } }];
}

const achaUm = (nome) => $(nome).all().map((i) => i.json).find((j) => j && j.id && !j.error) || null;

const principal = achaUm("Busca chamado principal");
if (!principal) return recusa("Chamado não encontrado.");

const f = principal.fields || {};
const b = $("Recebe pedido do app").first().json.body || {};
const texto = (v) => String(v ?? "").trim();
const agora = new Date().toISOString();
const numero = f.Numero_Chamado || "";
const historicoDe = (campos, linha) => ((campos.Historico ? campos.Historico + "\n" : "") + agora + " -- " + linha);
const grava = (registros) => [{ json: {
  chamadoId: principal.id, numeroChamado: numero, metodo: "PATCH", url: TABELA,
  corpo: { typecast: true, records: registros },
} }];

// ---- cancelar: só muda o status, sem exigir motivo e sem mexer no horário ----
if (texto(b.cancelar) === "true") {
  return grava([{ id: principal.id, fields: { Status: "Cancelado", Historico: historicoDe(f, "Chamado cancelado.") } }]);
}

// ---- tirar da agenda: volta pra fila, NÃO apaga o chamado ----
if (texto(b.desagendar) === "true") {
  return grava([{ id: principal.id, fields: {
    Reservado_Inicio: null, Reservado_Fim: null, Status: AGUARDANDO,
    Historico: historicoDe(f, "Tirado da agenda (voltou pra fila)."),
  } }]);
}

// ---- só confirmar/desconfirmar a data, mantendo o horário ----
if (texto(b.confirmarData) !== "") {
  const confirmar = texto(b.confirmarData) === "true";
  if (confirmar && !f.Reservado_Inicio) return recusa("Esse chamado ainda não tem data na agenda.");
  if (confirmar && !f.Reservado_Fim) return recusa("Escolha o horário exato antes de confirmar a data.");
  return grava([{ id: principal.id, fields: {
    Status: confirmar ? AGENDADO : AGUARDANDO,
    Historico: historicoDe(f, confirmar ? "Data confirmada." : "Data voltou para aguardando confirmação."),
  } }]);
}

// ---- daqui pra baixo é agendamento de verdade ----
const data = texto(b.data);
if (!data) return recusa("Pedido sem data.");

const semHorario = texto(b.semHorario) === "true";
const inicioHHMM = texto(b.reservadoInicio);
const fimHHMM = texto(b.reservadoFim);
if (!semHorario && (!inicioHHMM || !fimHHMM)) return recusa("Pedido sem horário.");

// dataFim vem separado de propósito: sem ele, um serviço que atravessa a
// meia-noite viraria "fim antes do início". Quando não vem, é o mesmo dia.
const dataFim = texto(b.dataFim) || data;
const novoInicioIso = isoBrasilia(data, semHorario ? "00:00" : inicioHHMM);
const novoFimIso = semHorario ? "" : isoBrasilia(dataFim, fimHHMM);
if (!semHorario && new Date(novoFimIso) <= new Date(novoInicioIso)) {
  return recusa("O fim tem que ser depois do início.");
}

// Parceiro da troca (opcional): ele recebe o horário que este aqui largou.
const trocarComId = texto(b.trocarComId);
const troca = trocarComId ? achaUm("Busca chamado da troca") : null;
if (trocarComId && !troca) return recusa("O outro chamado da troca não foi encontrado.");

const trocaDesagendar = texto(b.trocaDesagendar) === "true";
const trocaSemHorario = texto(b.trocaSemHorario) === "true";
const trocaData = texto(b.trocaData);
let trocaInicioIso = "", trocaFimIso = "";
if (troca && !trocaDesagendar) {
  if (!trocaData) return recusa("Troca sem data.");
  if (!trocaSemHorario && (!texto(b.trocaInicio) || !texto(b.trocaFim))) return recusa("Troca sem horário.");
  trocaInicioIso = isoBrasilia(trocaData, trocaSemHorario ? "00:00" : texto(b.trocaInicio));
  trocaFimIso = trocaSemHorario ? "" : isoBrasilia(texto(b.trocaDataFim) || trocaData, texto(b.trocaFim));
}

// Tudo que já está ocupado, tirando os próprios envolvidos. Um dia sem horário
// exato (só Reservado_Inicio, sem Fim) não ocupa faixa nenhuma -- ele ainda
// não é um horário de verdade.
const ativos = $("Busca chamados ativos").all().map((i) => i.json).filter((j) => j && j.id && !j.error);
const ocupados = ativos
  .filter((j) => (j.fields || {}).Reservado_Inicio && (j.fields || {}).Reservado_Fim)
  .filter((j) => j.id !== principal.id && j.id !== trocarComId)
  .map((j) => ({
    id: j.id, numero: j.fields.Numero_Chamado || "", cliente: j.fields.Cliente_Nome || "",
    inicioIso: j.fields.Reservado_Inicio, fimIso: j.fields.Reservado_Fim,
  }));

function checa(iniIso, fimIso) {
  if (!iniIso || !fimIso) return [];
  return ocupados
    .filter((o) => seCruzam(iniIso, fimIso, o.inicioIso, o.fimIso))
    .map((o) => ({ id: o.id, numero: o.numero, cliente: o.cliente, inicio: o.inicioIso, fim: o.fimIso }));
}

const conflitos = checa(novoInicioIso, novoFimIso);
const conflitosTroca = troca ? checa(trocaInicioIso, trocaFimIso) : [];
const batemEntreSi = Boolean(troca && novoFimIso && trocaFimIso
  && seCruzam(novoInicioIso, novoFimIso, trocaInicioIso, trocaFimIso));

if (conflitos.length || conflitosTroca.length || batemEntreSi) {
  const duracaoMs = novoFimIso ? new Date(novoFimIso) - new Date(novoInicioIso) : 0;
  const sugestao = duracaoMs ? achaHorarioLivre(data, duracaoMs, ocupados) : null;
  return recusa(
    batemEntreSi ? "Os dois horários da troca se cruzam." : "Esse horário já está ocupado.",
    { conflito: true, conflitos: conflitos.concat(conflitosTroca), sugestao }
  );
}

// Status: quem cai na agenda nasce "aguardando confirmação de data"; só vira
// "Agendado" quando o dono confirma. Quem já está em andamento continua como
// está. Dia sem horário exato NUNCA conta como confirmado.
function decideStatus(campos, pedido, semHora) {
  if (campos.Status === "Em andamento") return campos.Status;
  if (semHora) return AGUARDANDO;
  if (pedido === "confirmado") return AGENDADO;
  if (pedido === "aguardando") return AGUARDANDO;
  return campos.Status === AGENDADO ? AGENDADO : AGUARDANDO;
}

const linhaPrincipal = semHorario
  ? "agendado para " + data + ", horário ainda não definido."
  : "agendado para " + data + " das " + inicioHHMM + " às " + fimHHMM + ".";

const camposPrincipal = {
  Reservado_Inicio: novoInicioIso,
  Reservado_Fim: semHorario ? null : novoFimIso,
  Status: decideStatus(f, texto(b.statusAgendamento), semHorario),
  Historico: historicoDe(f, linhaPrincipal),
};
if (texto(b.horarioCombinadoCliente)) camposPrincipal.Horario_Combinado_Cliente = texto(b.horarioCombinadoCliente);

const registros = [{ id: principal.id, fields: camposPrincipal }];

if (troca) {
  const tf = troca.fields || {};
  if (trocaDesagendar) {
    registros.push({ id: troca.id, fields: {
      Reservado_Inicio: null, Reservado_Fim: null, Status: AGUARDANDO,
      Historico: historicoDe(tf, "Tirado da agenda junto com uma troca de horários."),
    } });
  } else {
    const linhaTroca = trocaSemHorario
      ? "trocou de lugar: " + trocaData + ", horário ainda não definido."
      : "trocou de lugar: " + trocaData + " das " + texto(b.trocaInicio) + " às " + texto(b.trocaFim) + ".";
    registros.push({ id: troca.id, fields: {
      Reservado_Inicio: trocaInicioIso,
      Reservado_Fim: trocaSemHorario ? null : trocaFimIso,
      Status: decideStatus(tf, texto(b.trocaStatus), trocaSemHorario),
      Historico: historicoDe(tf, linhaTroca),
    } });
  }
}

return grava(registros);

const b = $("Recebe pedido do app").first().json.body || {};
const texto = (v) => String(v ?? "").trim();
let mensagem = "Agendamento salvo!";
if (texto(b.cancelar) === "true") mensagem = "Chamado cancelado.";
else if (texto(b.desagendar) === "true") mensagem = "Chamado voltou pra fila.";
else if (texto(b.confirmarData) === "true") mensagem = "Data confirmada.";
else if (texto(b.confirmarData) === "false") mensagem = "Data voltou pra aguardando confirmação.";
else if (texto(b.trocarComId)) mensagem = "Horários trocados.";
return [{ json: { ok: true, mensagem } }];
